with m as (select id from trips where name='Maui 2026' limit 1)
insert into activities(trip_id,name,category,short_description,why_awesome,cost_level,status)
select m.id,x.name,x.category,x.d,x.d,x.cost,'idea' from m cross join (values ('Molokini Crater Snorkel','Ocean','Boat snorkel inside a volcanic crater with clear water and marine life.','$$$'),('Haleakalā Sunrise','Adventure','Watch sunrise above the clouds from more than 10,000 feet.','$'),('Family Surf Lesson','Ocean','Learn together; Bennett already has this high on his list.','$$$'),('Road to Hāna','Road Trip','Waterfalls, rainforest, coast and food stops in one choose-your-own-adventure day.','$$'),('Pīpīwai Trail + Waimoku Falls','Hike','Bamboo forest and a huge waterfall payoff in Kīpahulu.','$'),('Waiʻānapanapa Black Sand Beach','Beach','A dramatic black-sand coastline unlike a normal beach day.','$'),('Kapalua Bay','Beach','Beautiful bay and an easy beach plus snorkel candidate.','$'),('Puʻu Kekaʻa / Black Rock','Ocean','Classic Kāʻanapali snorkeling close to the resort zone.','$'),('Kapalua Coastal Trail','Hike','Easy coastal walk with lava rock, bays and huge views.','$'),('Waiheʻe Ridge Trail','Hike','A real ridge hike for mountain and valley views when weather cooperates.','$'),('Boogie Board Beach Day','Beach','Cheap, flexible and repeatable if everyone loves it.','$'),('Sunset Sail','Ocean','Get offshore for sunset without using the whole day.','$$$'),('Zipline','Adventure','A high-energy break from beaches and snorkeling.','$$$'),('ʻĪao Valley','Hike','Shorter lush-valley outing with iconic mountain scenery.','$'),('Upcountry Maui','Explore','Cooler air, farms and small towns after Haleakalā.','$$'),('Turtle Spotting / Shore Snorkel','Ocean','Look for honu respectfully at a conditions-appropriate snorkel spot.','$'),('Aunty Sandy''s Banana Bread','Food','Hot banana bread on the Keʻanae Peninsula — perfect for Hāna day.','$'),('Shave Ice Challenge','Food','Everyone rates their favorite. Extremely serious family research.','$'),('Leoda''s Pie Stop','Food','Sandwiches plus sweet and savory pies in Olowalu.','$$'),('Resort Pool + Beach Day','Chill','No driving, no schedule and no guilt about it.','$'),('Waterfall Swim Candidate','Adventure','Find a legal, safe, conditions-appropriate waterfall swim for Hāna day.','$'),('Kanahualii Falls Research','Hidden Gem','A Maui Revealed find from Dad; verify current access and conditions before planning.','$'),('Wildlife / Reef Photo Hunt','Ocean','Each person tries to photograph the coolest reef or wildlife sighting.','$'),('Family Pick Night','Food','One traveler gets to choose the dinner or treat stop.','$$')) x(name,category,d,cost)
where not exists(select 1 from activities a where a.trip_id=m.id and a.name=x.name);
with m as (select id from trips where name='Maui 2026' limit 1)
insert into packing_items(trip_id,name,category,is_shared,status)
select m.id,x.name,'Family',true,'need_to_pack' from m cross join (values ('Chargers + cables'),('Noise-canceling headphones'),('Sunscreen'),('Snorkeling gear'),('Warm Haleakalā layers'),('Power banks'),('Waterproof phone pouch'),('Medications / first aid')) x(name)
where not exists(select 1 from packing_items p where p.trip_id=m.id and p.name=x.name);